export const HERALDICA_DATA_URL = "data:image/png;base64,";

export async function loadHeraldica(): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = (e) => reject(e);
    img.src = HERALDICA_DATA_URL;
  });
}
